1	package shadow
2	
3	import (
4		"encoding/json"
5		"fmt"
6		"time"
7	)
8	
9	// diskVersion 是升级版本登记的磁盘格式。
10	type diskVersion struct {
11		Target      string   `json:"target"`
12		AllowedFrom []string `json:"allowedFrom"`
13	}
14	
15	// diskCampaign 是活动的磁盘格式，设备按提交次序保存。
16	type diskCampaign struct {
17		ID                string    `json:"id"`
18		Operator          string    `json:"operator"`
19		Target            string    `json:"target"`
20		CreatedAt         time.Time `json:"createdAt"`
21		BatchSize         int       `json:"batchSize"`
22		WindowStart       time.Time `json:"windowStart"`
23		WindowEnd         time.Time `json:"windowEnd"`
24		Deadline          time.Time `json:"deadline"`
25		RollbackOnFailure bool      `json:"rollbackOnFailure,omitempty"`
26		// IDScheme 是操作标识方案（opIDScheme*）；缺省为修复前的旧方案。
27		IDScheme int          `json:"idScheme,omitempty"`
28		LastTime time.Time    `json:"lastTime"`
29		Status   string       `json:"status"`
30		Ended    bool         `json:"ended"`
31		EndedAt  time.Time    `json:"endedAt,omitempty"`
32		Devices  []diskDev    `json:"devices"`
33		Results  []diskResult `json:"results,omitempty"`
34	}
35	
36	type diskOp struct {
37		ID            string          `json:"id"`
38		Claimed       bool            `json:"claimed"`
39		ClaimedAt     time.Time       `json:"claimedAt,omitempty"`
40		HasResult     bool            `json:"hasResult"`
41		Success       bool            `json:"success"`
42		Reason        string          `json:"reason,omitempty"`
43		At            time.Time       `json:"at,omitempty"`
44		ResultSeq     uint64          `json:"resultSeq,omitempty"`
45		ResultVersion string          `json:"resultVersion,omitempty"`
46		ResultConfig  json.RawMessage `json:"resultConfig,omitempty"`
47	}
48	
49	type diskDev struct {
50		DeviceID       string    `json:"deviceId"`
51		Batch          int       `json:"batch"`
52		Status         string    `json:"status"`
53		Phase          string    `json:"phase"`
54		Reason         string    `json:"reason,omitempty"`
55		At             time.Time `json:"at,omitempty"`
56		Download       diskOp    `json:"download"`
57		Install        diskOp    `json:"install"`
58		Rollback       diskOp    `json:"rollback,omitempty"`
59		RollbackTarget string    `json:"rollbackTarget,omitempty"`
60	}
61	
62	type diskResult struct {
63		DeviceID    string    `json:"deviceId"`
64		OperationID string    `json:"operationId"`
65		Stage       string    `json:"stage"`
66		Success     bool      `json:"success"`
67		Reason      string    `json:"reason,omitempty"`
68		Version     string    `json:"version,omitempty"`
69		At          time.Time `json:"at"`
70	}
71	
72	func (s *Store) marshalVersions() map[string]diskVersion {
73		out := make(map[string]diskVersion, len(s.versions))
74		for k, v := range s.versions {
75			out[k] = diskVersion{Target: v.Target, AllowedFrom: append([]string(nil), v.AllowedFrom...)}
76		}
77		return out
78	}
79	
80	func (s *Store) marshalCampaigns() (map[string]diskCampaign, error) {
81		out := make(map[string]diskCampaign, len(s.campaigns))
82		for id, c := range s.campaigns {
83			dc := diskCampaign{
84				ID:                c.ID,
85				Operator:          c.Operator,
86				Target:            c.Target,
87				CreatedAt:         c.CreatedAt,
88				BatchSize:         c.BatchSize,
89				WindowStart:       c.WindowStart,
90				WindowEnd:         c.WindowEnd,
91				Deadline:          c.Deadline,
92				RollbackOnFailure: c.RollbackOnFailure,
93				IDScheme:          c.idScheme,
94				LastTime:          c.LastTime,
95				Status:            c.Status,
96				Ended:             c.Ended,
97				EndedAt:           c.EndedAt,
98				Results:           make([]diskResult, 0, len(c.Results)),
99			}
100			for _, cd := range c.Devices {
101				dc.Devices = append(dc.Devices, diskDev{
102					DeviceID:       cd.DeviceID,
103					Batch:          cd.Batch,
104					Status:         cd.Status,
105					Phase:          cd.Phase,
106					Reason:         cd.Reason,
107					At:             cd.At,
108					Download:       encodeOp(cd.Download),
109					Install:        encodeOp(cd.Install),
110					Rollback:       encodeOp(cd.Rollback),
111					RollbackTarget: cd.RollbackTarget,
112				})
113			}
114			for _, r := range c.Results {
115				dc.Results = append(dc.Results, diskResult{
116					DeviceID:    r.DeviceID,
117					OperationID: r.OperationID,
118					Stage:       r.Stage,
119					Success:     r.Success,
120					Reason:      r.Reason,
121					Version:     r.Version,
122					At:          r.At,
123				})
124			}
125			out[id] = dc
126		}
127		return out, nil
128	}
129	
130	func encodeOp(o opState) diskOp {
131		return diskOp{
132			ID:            o.ID,
133			Claimed:       o.Claimed,
134			ClaimedAt:     o.ClaimedAt,
135			HasResult:     o.HasResult,
136			Success:       o.Success,
137			Reason:        o.Reason,
138			At:            o.At,
139			ResultSeq:     o.ResultSeq,
140			ResultVersion: o.ResultVersion,
141			ResultConfig:  cloneRaw(o.ResultConfig),
142		}
143	}
144	
145	func decodeOp(d diskOp) opState {
146		return opState{
147			ID:            d.ID,
148			Claimed:       d.Claimed,
149			ClaimedAt:     d.ClaimedAt,
150			HasResult:     d.HasResult,
151			Success:       d.Success,
152			Reason:        d.Reason,
153			At:            d.At,
154			ResultSeq:     d.ResultSeq,
155			ResultVersion: d.ResultVersion,
156			ResultConfig:  cloneRaw(d.ResultConfig),
157		}
158	}
159	
160	// restoreVersions 恢复并校验版本登记。
161	func (s *Store) restoreVersions(disk map[string]diskVersion) error {
162		out := make(map[string]*versionState, len(disk))
163		for k, dv := range disk {
164			if k == "" || dv.Target == "" || k != dv.Target {
165				return fmt.Errorf("%w: invalid upgrade version entry", ErrCorruptStorage)
166			}
167			if err := validateAllowedFrom(dv.Target, dv.AllowedFrom); err != nil {
168				return fmt.Errorf("%w: version %s: %v", ErrCorruptStorage, dv.Target, err)
169			}
170			out[k] = &versionState{Target: dv.Target, AllowedFrom: append([]string(nil), dv.AllowedFrom...)}
171		}
172		s.versions = out
173		return nil
174	}
175	
176	// expectedHist 是从已保存操作结果推导出的应有历史条目。
177	type expectedHist struct {
178		deviceID string
179		stage    string
180		op       diskOp
181	}
182	
183	// restoreCampaigns 恢复活动并做一致性校验。版本、设备引用、操作标识、
184	// 结果历史都必须自洽，否则整个存储拒绝打开。
185	func (s *Store) restoreCampaigns(disk map[string]diskCampaign) error {
186		out := make(map[string]*campaignState, len(disk))
187		for id, dc := range disk {
188			if id == "" || dc.ID != id {
189				return fmt.Errorf("%w: campaign id mismatch", ErrCorruptStorage)
190			}
191			if dc.Operator == "" || dc.Target == "" || dc.BatchSize <= 0 {
192				return fmt.Errorf("%w: campaign %s invalid", ErrCorruptStorage, id)
193			}
194			if dc.CreatedAt.IsZero() || dc.WindowStart.IsZero() || dc.WindowEnd.IsZero() || dc.Deadline.IsZero() {
195				return fmt.Errorf("%w: campaign %s missing time", ErrCorruptStorage, id)
196			}
197			if !dc.WindowStart.Before(dc.WindowEnd) || !dc.Deadline.After(dc.CreatedAt) {
198				return fmt.Errorf("%w: campaign %s invalid time range", ErrCorruptStorage, id)
199			}
200			if _, ok := s.versions[dc.Target]; !ok {
201				return fmt.Errorf("%w: campaign %s target %s missing", ErrCorruptStorage, id, dc.Target)
202			}
203			if dc.Status != CampaignRunning && dc.Status != CampaignSucceeded && dc.Status != CampaignFailed {
204				return fmt.Errorf("%w: campaign %s bad status", ErrCorruptStorage, id)
205			}
206			if dc.IDScheme != opIDSchemeLegacy && dc.IDScheme != opIDSchemeV2 {
207				return fmt.Errorf("%w: campaign %s unknown operation id scheme", ErrCorruptStorage, id)
208			}
209			if dc.Ended == (dc.Status == CampaignRunning) {
210				return fmt.Errorf("%w: campaign %s ended/status mismatch", ErrCorruptStorage, id)
211			}
212			if len(dc.Devices) == 0 {
213				return fmt.Errorf("%w: campaign %s has no devices", ErrCorruptStorage, id)
214			}
215			c := &campaignState{
216				ID:                dc.ID,
217				Operator:          dc.Operator,
218				Target:            dc.Target,
219				CreatedAt:         dc.CreatedAt,
220				BatchSize:         dc.BatchSize,
221				WindowStart:       dc.WindowStart,
222				WindowEnd:         dc.WindowEnd,
223				Deadline:          dc.Deadline,
224				RollbackOnFailure: dc.RollbackOnFailure,
225				idScheme:          dc.IDScheme,
226				LastTime:          dc.LastTime,
227				Status:            dc.Status,
228				Ended:             dc.Ended,
229				EndedAt:           dc.EndedAt,
230				index:             map[string]int{},
231			}
232			// 旧记录可能没有时间基线：缺省（零值）时仍以创建时间作为基线。
233			// 基线与各业务记录时间是否自洽在设备与历史全部恢复后统一检查。
234			if c.LastTime.IsZero() {
235				c.LastTime = c.CreatedAt
236			}
237			seen := map[string]bool{}
238			// expected 按操作标识收集每个已有结果（HasResult）的下载/安装/回滚
239			// 操作所对应的唯一应有历史条目，随后与保存的结果历史逐条对账。
240			expected := map[string]expectedHist{}
241			for i, dd := range dc.Devices {
242				if dd.DeviceID == "" || seen[dd.DeviceID] {
243					return fmt.Errorf("%w: campaign %s device list invalid", ErrCorruptStorage, id)
244				}
245				seen[dd.DeviceID] = true
246				if _, ok := s.devices[dd.DeviceID]; !ok {
247					return fmt.Errorf("%w: campaign %s device %s missing", ErrCorruptStorage, id, dd.DeviceID)
248				}
249				if dd.Batch != i/dc.BatchSize {
250					return fmt.Errorf("%w: campaign %s batch mismatch", ErrCorruptStorage, id)
251				}
252				if !validDeviceStatus(dd.Status) {
253					return fmt.Errorf("%w: campaign %s bad device status", ErrCorruptStorage, id)
254				}
255				if dd.Phase != StageDownload && dd.Phase != StageInstall && dd.Phase != StageRollback {
256					return fmt.Errorf("%w: campaign %s bad phase", ErrCorruptStorage, id)
257				}
258				if dc.IDScheme == opIDSchemeV2 {
259					// 新方案：标识必须是无歧义编码且恰好归属本活动、本设备、本阶段。
260					if !validV2OpID(dd.Download.ID, id, dd.DeviceID, StageDownload) ||
261						!validV2OpID(dd.Install.ID, id, dd.DeviceID, StageInstall) ||
262						!validV2OpID(dd.Rollback.ID, id, dd.DeviceID, StageRollback) {
263						return fmt.Errorf("%w: campaign %s operation id mismatch", ErrCorruptStorage, id)
264					}
265				} else {
266					wantDL := operationID(id, dd.DeviceID, StageDownload)
267					wantIN := operationID(id, dd.DeviceID, StageInstall)
268					wantRB := operationID(id, dd.DeviceID, StageRollback)
269					if dd.Download.ID != wantDL || dd.Install.ID != wantIN {
270						return fmt.Errorf("%w: campaign %s operation id mismatch", ErrCorruptStorage, id)
271					}
272					if dc.RollbackOnFailure {
273						if dd.Rollback.ID != wantRB {
274							return fmt.Errorf("%w: campaign %s rollback op id mismatch", ErrCorruptStorage, id)
275						}
276					} else if dd.Rollback.ID != "" && dd.Rollback.ID != wantRB {
277						// 未开启回滚的旧活动：回滚标识允许缺省或等于旧稳定标识。
278						return fmt.Errorf("%w: campaign %s rollback op id mismatch", ErrCorruptStorage, id)
279					}
280				}
281				if !dc.RollbackOnFailure {
282					// 未开启回滚的活动（含旧存储）不得残留任何回滚进展。
283					if dd.RollbackTarget != "" ||
284						dd.Rollback.Claimed || dd.Rollback.HasResult ||
285						dd.Status == DeviceAwaitingRollback || dd.Status == DeviceRollingBack ||
286						dd.Phase == StageRollback || isRollbackTerminal(dd.Status) {
287						return fmt.Errorf("%w: campaign %s rollback state in non-rollback campaign", ErrCorruptStorage, id)
288					}
289				}
290				// 终态设备必须带时间；失败还须带阶段与原因。
291				if isTerminal(dd.Status) && dd.At.IsZero() {
292					return fmt.Errorf("%w: campaign %s terminal without time", ErrCorruptStorage, id)
293				}
294				if dd.Status == DeviceFailed && dd.Reason == "" {
295					return fmt.Errorf("%w: campaign %s failure without reason", ErrCorruptStorage, id)
296				}
297				if (dd.Status == DeviceRollbackFailed || dd.Status == DeviceRollbackTimeout ||
298					dd.Status == DeviceAwaitingRollback) && dd.Reason == "" {
299					return fmt.Errorf("%w: campaign %s rollback without reason", ErrCorruptStorage, id)
300				}
301				if dd.Status == DeviceSucceeded &&
302					!(dd.Download.HasResult && dd.Download.Success && dd.Install.HasResult && dd.Install.Success) {
303					return fmt.Errorf("%w: campaign %s succeeded device without results", ErrCorruptStorage, id)
304				}
305				if dd.Status == DeviceFailed {
306					failedOp := dd.Download
307					if dd.Phase == StageInstall {
308						failedOp = dd.Install
309					}
310					if !failedOp.HasResult || failedOp.Success {
311						return fmt.Errorf("%w: campaign %s failed device without failed result", ErrCorruptStorage, id)
312					}
313				}
314				// ready（等待安装）与 installing（正在安装）都必须停留在安装阶段，
315				// 且只能依据本设备在本活动保存的下载/安装操作记录核对。
316				if err := validateInstallStageDisk(id, dd); err != nil {
317					return err
318				}
319				ops := []diskOp{dd.Download, dd.Install}
320				if dc.RollbackOnFailure {
321					ops = append(ops, dd.Rollback)
322				}
323				for _, o := range ops {
324					if o.HasResult {
325						if !o.Claimed {
326							return fmt.Errorf("%w: campaign %s unclaimed result", ErrCorruptStorage, id)
327						}
328						if o.At.IsZero() {
329							return fmt.Errorf("%w: campaign %s result without time", ErrCorruptStorage, id)
330						}
331						if !o.Success && o.Reason == "" {
332							return fmt.Errorf("%w: campaign %s failed result without reason", ErrCorruptStorage, id)
333						}
334					}
335					if o.Claimed && o.ClaimedAt.IsZero() {
336						return fmt.Errorf("%w: campaign %s claim without time", ErrCorruptStorage, id)
337					}
338				}
339				if dd.Install.HasResult && !(dd.Download.HasResult && dd.Download.Success) {
340					return fmt.Errorf("%w: campaign %s install before download", ErrCorruptStorage, id)
341				}
342				if dd.Install.Claimed && !(dd.Download.HasResult && dd.Download.Success) {
343					return fmt.Errorf("%w: campaign %s install claimed before download", ErrCorruptStorage, id)
344				}
345				if dd.Install.HasResult && dd.Install.Success {
346					if dd.Install.ResultVersion != dc.Target {
347						return fmt.Errorf("%w: campaign %s install version mismatch", ErrCorruptStorage, id)
348					}
349					if _, ok := decodeObject(dd.Install.ResultConfig); !ok {
350						return fmt.Errorf("%w: campaign %s install config invalid", ErrCorruptStorage, id)
351					}
352					if err := checkSuccessReport(id, dd, dd.Install, StageInstall, s.devices[dd.DeviceID]); err != nil {
353						return err
354					}
355				}
356				if dc.RollbackOnFailure {
357					if err := validateRollbackDisk(id, dd); err != nil {
358						return err
359					}
360				}
361				if dd.Rollback.HasResult && dd.Rollback.Success {
362					// 未开启回滚的活动存在回滚结果已在上方拒绝；这里只需核对
363					// 开启回滚的活动中已接受的回滚成功记录。
364					if err := checkSuccessReport(id, dd, dd.Rollback, StageRollback, s.devices[dd.DeviceID]); err != nil {
365						return err
366					}
367				}
368				rbOp := decodeOp(dd.Rollback)
369				if !dc.RollbackOnFailure {
370					// 与创建路径一致：内存中始终持有本方案稳定的回滚操作标识。
371					if dc.IDScheme == opIDSchemeV2 {
372						rbOp = opState{ID: dd.Rollback.ID}
373					} else {
374						rbOp = opState{ID: operationID(id, dd.DeviceID, StageRollback)}
375					}
376				}
377				cd := &campaignDevice{
378					DeviceID:       dd.DeviceID,
379					Batch:          dd.Batch,
380					Status:         dd.Status,
381					Phase:          dd.Phase,
382					Reason:         dd.Reason,
383					At:             dd.At,
384					Download:       decodeOp(dd.Download),
385					Install:        decodeOp(dd.Install),
386					Rollback:       rbOp,
387					RollbackTarget: dd.RollbackTarget,
388				}
389				c.index[cd.DeviceID] = len(c.Devices)
390				c.Devices = append(c.Devices, cd)
391				// 每个已有结果的操作都应当恰好对应一条结果历史；
392				// 已领取未完成、超时或因前批失败而未执行的阶段没有结果，不入账。
393				addExpected := func(o diskOp, stage string) {
394					if !o.HasResult {
395						return
396					}
397					expected[o.ID] = expectedHist{deviceID: dd.DeviceID, stage: stage, op: o}
398				}
399				addExpected(dd.Download, StageDownload)
400				addExpected(dd.Install, StageInstall)
401				if dc.RollbackOnFailure {
402					addExpected(dd.Rollback, StageRollback)
403				}
404			}
405			// seenHistory 记录已经与保存历史对过账的操作标识。
406			seenHistory := map[string]bool{}
407			var prevAt time.Time
408			for i, dr := range dc.Results {
409				if dr.At.IsZero() {
410					return fmt.Errorf("%w: campaign %s result without time", ErrCorruptStorage, id)
411				}
412				// 历史按接受顺序保存：时间不得倒退；同一时刻按保存次序排列。
413				if i > 0 && dr.At.Before(prevAt) {
414					return fmt.Errorf("%w: campaign %s result history out of order", ErrCorruptStorage, id)
415				}
416				prevAt = dr.At
417				if _, ok := c.index[dr.DeviceID]; !ok {
418					return fmt.Errorf("%w: campaign %s result device mismatch", ErrCorruptStorage, id)
419				}
420				if dr.Stage != StageDownload && dr.Stage != StageInstall && dr.Stage != StageRollback {
421					return fmt.Errorf("%w: campaign %s result stage invalid", ErrCorruptStorage, id)
422				}
423				if dr.Stage == StageRollback && !dc.RollbackOnFailure {
424					return fmt.Errorf("%w: campaign %s rollback result in non-rollback campaign", ErrCorruptStorage, id)
425				}
426				if dc.IDScheme == opIDSchemeLegacy {
427					// 旧方案标识可按（活动, 设备, 阶段）直接重算；新方案标识的
428					// 归属已在设备操作校验中确认，这里靠下方的历史对账锚定。
429					if wantOp := operationID(id, dr.DeviceID, dr.Stage); dr.OperationID != wantOp {
430						return fmt.Errorf("%w: campaign %s result op id mismatch", ErrCorruptStorage, id)
431					}
432				}
433				if seenHistory[dr.OperationID] {
434					return fmt.Errorf("%w: campaign %s duplicated result history", ErrCorruptStorage, id)
435				}
436				seenHistory[dr.OperationID] = true
437				// 历史必须对应该设备该阶段实际已有的结果：多出记录、设备或阶段不符
438				// 都按损坏处理，不能通过删历史或补结果把矛盾隐藏起来。
439				want, ok := expected[dr.OperationID]
440				if !ok {
441					return fmt.Errorf("%w: campaign %s result history without operation result", ErrCorruptStorage, id)
442				}
443				if want.deviceID != dr.DeviceID || want.stage != dr.Stage {
444					return fmt.Errorf("%w: campaign %s result history stage mismatch", ErrCorruptStorage, id)
445				}
446				if !dr.Success && dr.Reason == "" {
447					return fmt.Errorf("%w: campaign %s failed result without reason", ErrCorruptStorage, id)
448				}
449				o := want.op
450				if o.Success != dr.Success {
451					return fmt.Errorf("%w: campaign %s result history success mismatch", ErrCorruptStorage, id)
452				}
453				// 失败原因必须一致。成功结果的原因不进入历史（提交路径亦不拒绝
454				// 成功结果附带原因），故只对失败结果比对原因。
455				if !o.Success && o.Reason != dr.Reason {
456					return fmt.Errorf("%w: campaign %s result history reason mismatch", ErrCorruptStorage, id)
457				}
458				// 时间按同一时刻判断，不因时区表示不同而冲突。
459				if !o.At.Equal(dr.At) {
460					return fmt.Errorf("%w: campaign %s result history time mismatch", ErrCorruptStorage, id)
461				}
462				// 安装或回滚成功时记录的版本必须与当次操作接受的版本一致。
463				if dr.Success && (dr.Stage == StageInstall || dr.Stage == StageRollback) {
464					if dr.Version != o.ResultVersion || dr.Version == "" {
465						return fmt.Errorf("%w: campaign %s result history version mismatch", ErrCorruptStorage, id)
466					}
467				} else if dr.Version != "" {
468					// 下载成功及任何失败结果都不携带版本。
469					return fmt.Errorf("%w: campaign %s result history with unexpected version", ErrCorruptStorage, id)
470				}
471				c.Results = append(c.Results, ResultRecord{
472					DeviceID:    dr.DeviceID,
473					OperationID: dr.OperationID,
474					Stage:       dr.Stage,
475					Success:     dr.Success,
476					Reason:      dr.Reason,
477					Version:     dr.Version,
478					At:          dr.At,
479				})
480			}
481			// 反向对账：每个已有结果的操作都必须恰好有一条历史；缺少记录即损坏。
482			for opID, want := range expected {
483				if !seenHistory[opID] {
484					return fmt.Errorf("%w: campaign %s device %s %s result missing history",
485						ErrCorruptStorage, id, want.deviceID, want.stage)
486				}
487			}
488			// 活动整体结论必须与设备进度一致：与接收设备结果时的 settle 共用
489			// campaignConclusion 的同一套结论规则——任一设备仍处于非终态（等待下载、
490			// 下载中、等待安装、安装中、等待回滚、回滚中），活动必须 running 且
491			// Ended 为 false；全部设备终态时活动必须已结束，且只有每台设备都
492			// succeeded 才能 succeeded，其余组合（失败、超时、未执行，以及回滚
493			// 成功/失败/超时——回滚成功只是恢复原版本，不算本次升级成功）只能
494			// failed。设备离线或维护窗口结束不改变这一判断。
495			wantEnded, wantStatus := campaignConclusion(c)
496			if !wantEnded {
497				if c.Ended || c.Status != wantStatus {
498					return fmt.Errorf("%w: campaign %s ended while devices unfinished", ErrCorruptStorage, id)
499				}
500			} else {
501				if !c.Ended || c.Status != wantStatus {
502					return fmt.Errorf("%w: campaign %s status %s does not match device results",
503						ErrCorruptStorage, id, c.Status)
504				}
505			}
506			// 批次放行顺序必须与保存的升级结果自洽：任一设备首次领取下载时，
507			// 较早批次的每台设备都必须已经首次接受“安装成功”结果，且其成功
508			// 时间不晚于该次下载领取时间。只看活动保存的结果，不看设备当前在线
509			// 状态或当前版本；下载成功、安装中、安装失败后等待回滚、已回滚等
510			// 都不算放行。该核对对仍在执行和已结束的活动都生效，下载后来的
511			// 成功、失败或超时不能掩盖首次领取时越批的矛盾。
512			if err := checkCampaignBatchRelease(id, c); err != nil {
513				return err
514			}
515			// 每个已领取操作的首次领取时间必须落在活动保存的原维护窗口内；
516			// 窗口外的首次领取不能当作有效进度接受，也不能靠挪动领取时间、
517			// 撤销领取或重写进度来消除矛盾。
518			if err := checkCampaignClaimWindow(id, c); err != nil {
519				return err
520			}
521			// 时间基线必须能解释全部已存在的业务记录，否则重开后本应被拒绝的
522			// 旧时间请求又能推进活动。不能抬高基线或改写任何记录来掩盖矛盾。
523			if err := checkCampaignTimeBaseline(id, c); err != nil {
524				return err
525			}
526			// 已接受结果的操作，其首次结果发生时间不得早于该操作自己的首次领取
527			// 时间；结果先于领取发生在因果上不可能，不能靠其他设备的领取时间、
528			// 设备影子的最近上报时间或活动结束时间把它“合法化”。
529			if err := checkCampaignResultOrder(id, c); err != nil {
530				return err
531			}
532			// 已接受结果的操作，其首次结果发生时间还必须严格早于活动截止时间；
533			// 截止时刻及以后正常提交路径不再接收结果，已有存储中的迟到结果不能
534			// 当作有效进度读取。
535			if err := checkCampaignResultDeadline(id, c); err != nil {
536				return err
537			}
538			out[id] = c
539		}
540		// 设备不能同时参加多个未结束活动。
541		busy := map[string]string{}
542		for id, c := range out {
543			if c.Ended {
544				continue
545			}
546			for _, cd := range c.Devices {
547				if other, ok := busy[cd.DeviceID]; ok {
548					return fmt.Errorf("%w: device %s in active campaigns %s and %s",
549						ErrCorruptStorage, cd.DeviceID, other, id)
550				}
551				busy[cd.DeviceID] = id
552			}
553		}
554		s.campaigns = out
555		return nil
556	}
