558	// checkCampaignBatchRelease 核对活动的批次放行顺序与保存的升级结果自洽：
559	// 任一已经领取过下载的设备，在其首次领取下载时，所有较早批次的设备都必须
560	// 已经成功完成安装，且每台前序设备首次接受安装成功结果的时间不晚于该次
561	// 下载的首次领取时间。只按活动保存的升级结果判断：设备当前是否在线、当前
562	// 版本是否恰好等于目标版本都不能替代前序安装成功；前序设备仅下载成功、
563	// 正在安装、安装失败后等待回滚或已经回滚成功均不满足放行条件。
564	// 尚未领取下载的设备（正常等待后批、因前批失败而未执行、未领取即随截止
565	// 超时）不参与核对，也不能仅因前批没有成功而拒绝。时间按同一时刻比较，
566	// 时区写法不同不视为矛盾；同一时刻合法。核对对仍在执行和已结束的活动都
567	// 生效，下载后来成功、失败或超时都不能掩盖首次领取时越过前批的问题。
568	func checkCampaignBatchRelease(campaignID string, c *campaignState) error {
569		for _, cd := range c.Devices {
570			if !cd.Download.Claimed || cd.Download.ClaimedAt.IsZero() {
571				continue
572			}
573			claimedAt := cd.Download.ClaimedAt
574			for _, prev := range c.Devices {
575				if prev.Batch >= cd.Batch {
576					// 同批设备各自推进，不等待同批其他设备；更晚批次不相关。
577					continue
578				}
579				if !(prev.Install.HasResult && prev.Install.Success) {
580					return fmt.Errorf("%w: campaign %s device %s download claimed while previous-batch device %s not installed",
581						ErrCorruptStorage, campaignID, cd.DeviceID, prev.DeviceID)
582				}
583				// time.Time 的比较按绝对时刻进行，不因时区写法不同而拒绝
584				// 相同时刻；安装成功时刻晚于下载领取时刻即属越批领取，相等合法。
585				if prev.Install.At.After(claimedAt) {
586					return fmt.Errorf("%w: campaign %s device %s download claimed at %s before device %s install succeeded at %s",
587						ErrCorruptStorage, campaignID, cd.DeviceID,
588						claimedAt.Format(time.RFC3339Nano), prev.DeviceID, prev.Install.At.Format(time.RFC3339Nano))
589				}
590			}
591		}
592		return nil
593	}
594	
595	// checkCampaignClaimWindow 核对每个已领取的下载/安装/回滚操作的首次领取时间
596	// 都落在活动保存的原维护窗口 [start, end) 内：开始时刻包含、结束时刻不包含。
597	// 首次领取必须遵守维护窗口——早于开始或恰好到达、晚于结束的领取记录都使整个
598	// 存储损坏，即使其余状态与结果历史完全自洽、活动仍在执行或已成功/失败结束、
599	// 该操作后来成功、失败或超时，也不能把窗口外的首次领取当作有效进度接受，
600	// 更不能通过挪动领取时间、撤销领取、删去活动或重写进度来消除矛盾。
601	// 这项核对只针对真正首次领取的时刻：尚未领取的操作没有领取时间（等待下载、
602	// 等待安装、等待回滚及未领取便结束的记录），属正常缺省，不参与核对；未开启
603	// 回滚的活动内存中只有缺省的回滚操作标识，不算已领取。已经在窗口内领取的
604	// 操作，后来在窗口外的重复查询、截止前的结果接受以及活动结束时间都不要求
605	// 重新满足窗口。比较按绝对时刻进行，时区写法不同不视为矛盾。
606	func checkCampaignClaimWindow(campaignID string, c *campaignState) error {
607		for _, cd := range c.Devices {
608			ops := []struct {
609				stage string
610				op    *opState
611			}{
612				{StageDownload, &cd.Download},
613				{StageInstall, &cd.Install},
614				{StageRollback, &cd.Rollback},
615			}
616			for _, item := range ops {
617				if !item.op.Claimed {
618					continue
619				}
620				at := item.op.ClaimedAt
621				// 窗口为 [start, end)：恰好到达开始合法，恰好到达结束不合法。
622				// time.Time 的比较按绝对时刻进行，同一时刻的不同时区写法结果相同。
623				if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
624					return fmt.Errorf("%w: campaign %s device %s %s first claimed at %s outside maintenance window [%s, %s)",
625						ErrCorruptStorage, campaignID, cd.DeviceID, item.stage,
626						at.Format(time.RFC3339Nano),
627						c.WindowStart.Format(time.RFC3339Nano),
628						c.WindowEnd.Format(time.RFC3339Nano))
629				}
630			}
631		}
632		return nil
633	}
