635	// checkCampaignTimeBaseline 校验活动时间基线（已接受的最新时间）与保存的
636	// 业务记录自洽：基线必须不早于创建时间、任一设备已经领取下载/安装/回滚的
637	// 时间、任一操作首次接受结果的时间、设备当前状态中已记录的时间；活动已结束
638	// 时还必须不早于保存的结束时间。只比较确实存在的记录：尚未领取的操作没有
639	// 领取时间、尚未接受结果的操作没有结果时间、新建且尚未推进的设备允许没有
640	// 状态时间，这些正常缺省值不导致打开失败。比较按绝对时刻进行，相等合法。
641	func checkCampaignTimeBaseline(campaignID string, c *campaignState) error {
642		baseline := c.LastTime
643		bad := func(format string, args ...any) error {
644			msg := fmt.Sprintf(format, args...)
645			return fmt.Errorf("%w: campaign %s time baseline %s %s",
646				ErrCorruptStorage, campaignID, baseline.Format(time.RFC3339Nano), msg)
647		}
648		if baseline.Before(c.CreatedAt) {
649			return bad("before creation time %s", c.CreatedAt.Format(time.RFC3339Nano))
650		}
651		if c.Ended && !c.EndedAt.IsZero() && baseline.Before(c.EndedAt) {
652			return bad("before end time %s", c.EndedAt.Format(time.RFC3339Nano))
653		}
654		for _, cd := range c.Devices {
655			if !cd.At.IsZero() && baseline.Before(cd.At) {
656				return bad("before device %s state time %s",
657					cd.DeviceID, cd.At.Format(time.RFC3339Nano))
658			}
659			// 已领取（含尚未完成）的操作一定接受过携带领取时刻的请求；
660			// 已接受结果的操作还必须比较首次接受结果的时间。未领取/未接受
661			// 的操作对应时间为零值，属正常缺省，跳过比较。
662			ops := []struct {
663				stage string
664				op    *opState
665			}{
666				{StageDownload, &cd.Download},
667				{StageInstall, &cd.Install},
668				{StageRollback, &cd.Rollback},
669			}
670			for _, item := range ops {
671				if !item.op.ClaimedAt.IsZero() && baseline.Before(item.op.ClaimedAt) {
672					return bad("before device %s %s claim time %s",
673						cd.DeviceID, item.stage, item.op.ClaimedAt.Format(time.RFC3339Nano))
674				}
675				if item.op.HasResult && !item.op.At.IsZero() && baseline.Before(item.op.At) {
676					return bad("before device %s %s result time %s",
677						cd.DeviceID, item.stage, item.op.At.Format(time.RFC3339Nano))
678				}
679			}
680		}
681		return nil
682	}
683	
684	// checkCampaignResultOrder 校验每个已经接受结果的下载/安装/回滚操作，其首次
685	// 结果发生时间都不早于该操作自己的首次领取时间：同一活动、同一设备、同一阶段
686	// 的两个时刻直接比较，成功与失败适用同一规则。结果先于领取在因果上不可能，
687	// 必须使整个存储拒绝打开；不能用其他设备的领取时间、设备影子的最近上报时间、
688	// 活动的最新时间或结束时间替代这两个时刻，也不能通过修改时间、删除结果历史、
689	// 撤销领取或改变设备状态让记录变得合法。后来安装成功或回滚完成同样不能掩盖
690	// 早先阶段的矛盾，因此该核对对仍在执行和已结束的活动都生效。
691	// 只比较该操作自己确实存在的两个时刻：尚未接受结果（含已领取未完成、随后因
692	// 截止超时）的操作没有结果时间，尚未领取的等待步骤没有领取时间，均属正常
693	// 缺省，跳过核对。首次领取时因版本不兼容而直接形成的下载失败，领取与失败
694	// 可以是同一时刻；两时刻相等合法。已领取操作在窗口结束后、截止前提交结果
695	// 不受限制——本核对不要求结果落在维护窗口内。比较按绝对时刻进行，时区写法
696	// 不同不视为矛盾。重复提交不覆盖首次记录，这里使用的就是首次接受的两个时刻。
697	func checkCampaignResultOrder(campaignID string, c *campaignState) error {
698		for _, cd := range c.Devices {
699			ops := []struct {
700				stage string
701				op    *opState
702			}{
703				{StageDownload, &cd.Download},
704				{StageInstall, &cd.Install},
705				{StageRollback, &cd.Rollback},
706			}
707			for _, item := range ops {
708				o := item.op
709				// 未接受结果（含已领取未完成、超时）或未领取的操作不参与核对：
710				// HasResult 为 true 时上方的操作校验已保证 Claimed 且两个时间非零。
711				if !o.HasResult {
712					continue
713				}
714				// time.Time 的比较按绝对时刻进行：结果早于首次领取即损坏，
715				// 相同时刻的不同时区写法结果相同，相等合法。
716				if o.At.Before(o.ClaimedAt) {
717					return fmt.Errorf("%w: campaign %s device %s %s result at %s before first claim at %s",
718						ErrCorruptStorage, campaignID, cd.DeviceID, item.stage,
719						o.At.Format(time.RFC3339Nano), o.ClaimedAt.Format(time.RFC3339Nano))
720				}
721			}
722		}
723		return nil
724	}
725	
726	// checkCampaignResultDeadline 校验每个已经接受结果的下载/安装/回滚操作，其首次
727	// 结果发生时间都严格早于所属活动的截止时间：正常提交路径在截止时刻及以后不再
728	// 把结果接收为操作结果（已领取未完成的操作随截止记为超时），因此已有存储中
729	// 等于或晚于截止的结果时间不可能由正常提交产生，必须使整个存储拒绝打开。
730	// 成功与失败适用同一规则；恰好等于截止时间也属于迟到。比较按绝对时刻进行，
731	// 时区写法不同不改变判断。该核对对仍在执行和已结束的活动都生效：设备后来
732	// 安装成功、回滚完成或当前版本恰好等于目标版本，都不能让早先的迟到结果合法。
733	// 只比较操作自己确实保存的结果时间：已领取但尚无结果、随后因截止而超时的操作
734	// 没有结果时间，属正常缺省，不参与核对；活动的超时状态时间与结束时间可以等于
735	// 或晚于截止，普通设备上报也不受这项限制，这些时间不能代替操作结果时间参与
736	// 判断。截止前已接受的结果后来重复提交时不改写首次记录，这里使用的是首次接受
737	// 的时刻，不按重复提交时间判断。命中任意一条都必须返回 ErrCorruptStorage，
738	// 不能通过删除迟到结果、调整时间或把设备改成超时来继续打开。
739	func checkCampaignResultDeadline(campaignID string, c *campaignState) error {
740		for _, cd := range c.Devices {
741			ops := []struct {
742				stage string
743				op    *opState
744			}{
745				{StageDownload, &cd.Download},
746				{StageInstall, &cd.Install},
747				{StageRollback, &cd.Rollback},
748			}
749			for _, item := range ops {
750				o := item.op
751				// 未接受结果（含已领取未完成、随后超时）的操作没有结果时间，
752				// 属正常缺省，跳过核对。
753				if !o.HasResult {
754					continue
755				}
756				// time.Time 的比较按绝对时刻进行：结果不早于截止（相等或更晚）
757				// 即属迟到，同一时刻的不同时区写法判断相同。
758				if !o.At.Before(c.Deadline) {
759					return fmt.Errorf("%w: campaign %s device %s %s result at %s not before deadline %s",
760						ErrCorruptStorage, campaignID, cd.DeviceID, item.stage,
761						o.At.Format(time.RFC3339Nano), c.Deadline.Format(time.RFC3339Nano))
762				}
763			}
764		}
765		return nil
766	}
767	
768	// checkSuccessReport 核对一条已接受的安装/回滚成功记录保存的附带上报与
769	// 对应设备影子最近接受的上报之间的关系。序号必须是正整数且不大于设备最近
770	// 接受的序号：缺失、为零或大于设备记录都按损坏处理。两边序号相等时，这条
771	// 成功记录代表的就是设备最近一次上报，其版本、完整上报配置与首次接受结果时
772	// 保存的发生时间必须分别与影子保存的版本、上报配置和最近上报时间一致
773	// （配置按 JSON 语义比较，时间按同一时刻判断，不因时区表示不同而报错）。
774	// 序号更小则是已被后续上报覆盖的历史记录，不要求与当前影子一致。
775	// 设备当前是否在线不影响本核对；下载结果、失败结果与没有成功结果的阶段
776	// 不保存附带上报序号，也不进入本核对。
777	func checkSuccessReport(campaignID string, dd diskDev, o diskOp, stage string, d *deviceState) error {
778		bad := func(format string, args ...any) error {
779			msg := fmt.Sprintf(format, args...)
780			return fmt.Errorf("%w: campaign %s device %s %s success report %s",
781				ErrCorruptStorage, campaignID, dd.DeviceID, stage, msg)
782		}
783		if o.ResultSeq == 0 {
784			return bad("missing report sequence")
785		}
786		if o.ResultSeq > d.LastSeq {
787			return bad("sequence %d not accepted by device (last accepted %d)", o.ResultSeq, d.LastSeq)
788		}
789		if o.ResultSeq == d.LastSeq {
790			if o.ResultVersion != d.Version {
791				return bad("version %s does not match latest reported version %s", o.ResultVersion, d.Version)
792			}
793			if !rawEqual(o.ResultConfig, d.Reported) {
794				return bad("config does not match latest reported config")
795			}
796			if !o.At.Equal(d.LastReportTime) {
797				return bad("time %s does not match latest report time %s",
798					o.At.Format(time.RFC3339Nano), d.LastReportTime.Format(time.RFC3339Nano))
799			}
800		}
801		return nil
802	}
