804	func validDeviceStatus(status string) bool {
805		switch status {
806		case DevicePending, DeviceDownloading, DeviceReady, DeviceInstalling,
807			DeviceSucceeded, DeviceFailed, DeviceTimeout, DeviceSkipped,
808			DeviceAwaitingRollback, DeviceRollingBack,
809			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
810			return true
811		default:
812			return false
813		}
814	}
815	
816	// isRollbackTerminal 判断状态是否属于回滚相关终态。
817	func isRollbackTerminal(status string) bool {
818		switch status {
819		case DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
820			return true
821		default:
822			return false
823		}
824	}
825	
826	// isRollbackFlowStatus 判断状态是否处于回滚流程（等待/进行中/任一回滚终态）。
827	func isRollbackFlowStatus(status string) bool {
828		switch status {
829		case DeviceAwaitingRollback, DeviceRollingBack,
830			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
831			return true
832		default:
833			return false
834		}
835	}
836	
837	// validateInstallStageDisk 校验 ready（等待安装）与 installing（正在安装）两种
838	// 设备状态与本设备在本活动中保存的操作进度一致。两种状态都必须已有本设备接受
839	// 的下载成功结果并停留在安装阶段：ready 表示安装从未领取、尚无安装结果；
840	// installing 表示安装已经领取、但还没有接受安装结果。即使操作标识、时间与结果
841	// 历史各自合法，已完成安装（安装成功或失败已有结果）的设备也不能解释成仍在
842	// 等待或正在安装，安装已经领取的记录同样不能停在 ready。核对只看本设备本活动
843	// 的下载/安装操作记录：不能借用同批其他设备的下载成功，也不能用设备当前版本
844	// 恰好等于目标版本替代下载或安装结果。尚未领取安装时没有安装领取时间、尚无
845	// 安装结果时没有结果时间，是正常缺省；设备离线、维护窗口已结束或普通上报改变
846	// 了当前版本都不在此核对范围内。矛盾一律返回 ErrCorruptStorage，拒绝打开整个
847	// 存储，不通过调整状态、撤销领取、删除历史或补造结果消除矛盾。
848	func validateInstallStageDisk(campaignID string, dd diskDev) error {
849		bad := func(msg string) error {
850			return fmt.Errorf("%w: campaign %s device %s %s", ErrCorruptStorage, campaignID, dd.DeviceID, msg)
851		}
852		switch dd.Status {
853		case DeviceReady, DeviceInstalling:
854		default:
855			return nil
856		}
857		if dd.Phase != StageInstall {
858			return bad("install-stage status without install phase")
859		}
860		// 两种状态都必须有本设备在本活动中已接受的下载成功结果。
861		if !(dd.Download.HasResult && dd.Download.Success) {
862			return bad("install-stage status without accepted download success")
863		}
864		switch dd.Status {
865		case DeviceReady:
866			// 等待安装：安装从未领取、尚无安装结果；没有安装领取时间与结果时间
867			// 是正常缺省。安装已领取或已有成功/失败结果都与 ready 矛盾。
868			if dd.Install.Claimed || dd.Install.HasResult {
869				return bad("ready state with install claimed or resulted")
870			}
871		case DeviceInstalling:
872			// 正在安装：安装已经领取，但还没有接受安装结果（成功或失败都不行）。
873			if !dd.Install.Claimed {
874				return bad("installing state without install claim")
875			}
876			if dd.Install.HasResult {
877				return bad("installing state with install result")
878			}
879		}
880		return nil
881	}
882	
883	// validateRollbackDisk 校验开启回滚的活动中单台设备的回滚状态自洽。
884	func validateRollbackDisk(campaignID string, dd diskDev) error {
885		bad := func(msg string) error {
886			return fmt.Errorf("%w: campaign %s device %s %s", ErrCorruptStorage, campaignID, dd.DeviceID, msg)
887		}
888		rb := dd.Rollback
889		// 回滚目标只能在首次领取下载时或之后锁定：有目标就必已领取下载。
890		// 反向不成立——领取下载时复查版本不兼容会直接失败，不锁定目标、也不回滚。
891		if dd.RollbackTarget != "" && !dd.Download.Claimed {
892			return bad("rollback target locked before download claim")
893		}
894		// 已领取下载且尚无下载结果，或已有成功下载结果：回滚目标必须已锁定，
895		// 字段缺失与空串按同一种损坏处理。这项要求不因设备进入安装阶段或
896		// 活动已结束而取消——否则安装失败后会留下没有明确恢复版本的回滚待办。
897		// 不能用当前影子版本、活动目标版本或允许升级列表替代丢失的目标。
898		// 首次领取前复查版本不兼容、直接在下载阶段失败的设备（下载已有失败
899		// 结果）允许没有目标：这种失败不进入安装或回滚。
900		if dd.RollbackTarget == "" && dd.Download.Claimed &&
901			(!dd.Download.HasResult || dd.Download.Success) {
902			return bad("missing locked rollback target")
903		}
904		// 进入回滚流程的设备必然经过成功下载，目标一定已锁定。
905		if isRollbackFlowStatus(dd.Status) && dd.RollbackTarget == "" {
906			return bad("rollback status without locked target")
907		}
908		// 回滚流程的唯一入口是“已接受本次安装的失败结果”：等待回滚、正在回滚
909		// 以及回滚成功/失败/超时的设备，都必须能从本设备在本活动中已经接受的
910		// 安装结果确认安装失败。安装尚未领取、已领取但没有结果，或安装结果为
911		// 成功，都不能支持任何回滚状态；即使回滚目标非空、操作标识合法、回滚
912		// 结果与历史一致或活动已结束，也必须核对这一前提。当前版本恰好等于旧
913		// 版本、下载失败以及其他设备或其他活动的失败记录都不能代替本次安装失败
914		// （这里只看本设备本活动保存的安装操作结果本身）。
915		installFailed := dd.Install.HasResult && !dd.Install.Success
916		if isRollbackFlowStatus(dd.Status) && !installFailed {
917			return bad("rollback state without accepted install failure")
918		}
919		switch dd.Status {
920		case DeviceAwaitingRollback:
921			// 已接受安装失败、回滚尚未领取：回滚无结果。
922			if dd.Phase != StageRollback || rb.Claimed || rb.HasResult {
923				return bad("awaiting rollback state mismatch")
924			}
925		case DeviceRollingBack:
926			if dd.Phase != StageRollback || !rb.Claimed || rb.HasResult {
927				return bad("rolling back state mismatch")
928			}
929		case DeviceRollbackSucceeded:
930			if dd.Phase != StageRollback || !rb.HasResult || !rb.Success {
931				return bad("rollback succeeded without success result")
932			}
933			if rb.ResultVersion != dd.RollbackTarget {
934				return bad("rollback version mismatch")
935			}
936			if _, ok := decodeObject(rb.ResultConfig); !ok {
937				return bad("rollback config invalid")
938			}
939		case DeviceRollbackFailed:
940			if dd.Phase != StageRollback || !rb.HasResult || rb.Success || rb.Reason == "" {
941				return bad("rollback failed without failure result")
942			}
943		case DeviceRollbackTimeout:
944			if dd.Phase != StageRollback {
945				return bad("rollback timeout phase mismatch")
946			}
947			// 等待回滚超时（未领取）或正在回滚超时（已领取未完成）都可能。
948			if rb.HasResult {
949				return bad("rollback timeout with result")
950			}
951		default:
952			// 其余状态：开启回滚后安装一旦失败必然进入回滚流程，
953			// 因此这里不能有安装失败，回滚操作也必须从未被领取或提交；
954			// 但回滚目标可能因已领取下载而存在（下载失败/超时/成功等）。
955			if dd.Install.HasResult && !dd.Install.Success {
956				return bad("install failure without rollback state")
957			}
958			if rb.Claimed || rb.HasResult {
959				return bad("rollback progressed without install failure")
960			}
961		}
962		return nil
963	}
964

