145		// 只能由 ready 进度核对发现矛盾。
146		t.Run("ready with install claimed", func(t *testing.T) {
147			_, dir, spec := setupReady(t)
148			original := mutateDeviceOp(t, dir, spec.ID, "d1", "install", func(o map[string]any) {
149				o["claimed"] = true
