151			})
152			assertReopenCorrupt(t, dir, original)
153		})
154	
155		// 已有安装成功结果（配套历史、附带上报与设备影子全部自洽，当前版本已等于
156		// 目标版本，时间基线也覆盖全部记录）却保存为 ready：已完成安装的设备不能
157		// 解释成仍在等待安装。
158		t.Run("ready with install success result", func(t *testing.T) {
159			s, spec := buildReadyOpen(t)
160			// 与安装结果同一时刻的普通上报：版本 v2、配置 {}、序号 2，使附带上报
