		assertReopenCorrupt(t, dir, original)
	})
	t.Run("history emptied", func(t *testing.T) {
		_, dir, _ := setupReady(t)
		original := rewriteStoreBytes(t, dir, func(doc map[string]any) {
			campaignDoc(doc, "cmp-1")["results"] = []any{}
		})
