		s, dir, spec := buildBatchGateStore(t)
		s.Close()
		setDownloadClaimedAt(t, dir, spec.ID, "b3", "2026-10-02T12:23:00Z")
		s2, err := Open(dir)
		if err != nil {
			t.Fatalf("claim at equal instant must open: %v", err)
		}
		defer s2.Close()
		w, err := s2.GetDeviceWork("b3")
		if err != nil {
			t.Fatal(err)
		}
